[Fact]
public async Task DelayAsync_ConcurrentCalls_ShouldCompleteIndependently()
{
    // Arrange
    var delayProvider = new DelayProvider();
    var tasks = new List<Task>();
    var delayTimes = new[] { 100, 200, 300 };
    var startTime = DateTime.UtcNow;

    // Act
    foreach (var delay in delayTimes)
    {
        tasks.Add(Task.Run(async () =>
        {
            await delayProvider.DelayAsync(delay);
        }));

    await Task.WhenAll(tasks);
    var endTime = DateTime.UtcNow;

    // Assert
    var totalElapsedTime = (endTime - startTime).TotalMilliseconds;
    Assert.True(totalElapsedTime >= 300, $"Total elapsed time ({totalElapsedTime}ms) should be at least 300ms");
    Assert.True(totalElapsedTime < 400, $"Total elapsed time ({totalElapsedTime}ms) should be less than 400ms, indicating concurrent execution");

