[Fact]
public async Task DelayAsync_WithCancellationToken_CompletesWithoutCancellation()
{
    // Arrange
    var delayProvider = new DelayProvider();
    var cancellationTokenSource = new CancellationTokenSource();
    int delayMilliseconds = 100;

    // Act
    var delayTask = delayProvider.DelayAsync(delayMilliseconds, cancellationTokenSource.Token);
    
    // Assert
    await Assert.ThrowsAsync<TimeoutException>(() => delayTask.TimeoutAfter(50));
    
    await Task.Delay(delayMilliseconds + 10); // Wait a little longer than the delay
    
    Assert.True(delayTask.IsCompleted, "The delay task should have completed.");
    Assert.False(delayTask.IsCanceled, "The delay task should not have been cancelled.");

